// Contains all prompts for the 'Business' category.
export const businessPrompts = [

  // ── HR: Recruitment & Hiring (b-1 to b-10) ──────────────────────────────

  {"id":"b-1","title":"Job Description Writer","prompt":"You are a senior HR strategist with 15 years of talent acquisition experience. Write a complete, compelling job description for a Senior Product Manager at a B2B SaaS company with 50–200 employees. The description should include: a two-sentence role summary that speaks to ambitious candidates, 6–8 specific day-to-day responsibilities, clearly separated required qualifications (5 items) versus nice-to-have qualifications (3 items), a compensation transparency section with salary range ($130,000–$160,000) and equity (0.1–0.3%), a benefits overview that emphasizes flexibility and growth, and a 'Why This Role' closing paragraph written in a warm, direct tone. Avoid corporate jargon. The tone should attract candidates who are self-directed and impact-driven.","tags":["hr","hiring","job-description"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-2","title":"Structured Interview Question Builder","prompt":"You are a certified HR professional specializing in behavioral interviewing. Create a structured interview guide for hiring a Head of Customer Success at a Series B SaaS startup with 80 employees. Build 5 behavioral questions using the STAR format (Situation, Task, Action, Result) that test for ownership, customer empathy, cross-functional collaboration, data-driven decision-making, and resilience under pressure. For each question, write: the question itself, a follow-up probe question, and a scoring rubric with descriptions for responses at levels 1 (poor), 3 (acceptable), and 5 (exceptional). Format the guide as a clean document interviewers can print and use.","tags":["hr","interviewing","hiring"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-3","title":"Candidate Rejection Email With Feedback","prompt":"You are an HR communications specialist who believes every candidate deserves a respectful experience. Write a rejection email for a candidate who interviewed for a Senior Software Engineer (Backend) role and reached the final round but was not selected. The company is a fintech startup of 120 people. The email should: open with genuine acknowledgment of their time and effort, clearly state the decision without ambiguity, offer one specific and constructive piece of feedback that is honest but encouraging (the candidate's system design answers lacked distributed systems depth), invite them to apply again in 6 months for future roles, and close with a personal, non-generic sign-off. Keep the email under 220 words. The tone must be warm, direct, and human — not corporate boilerplate.","tags":["hr","hiring","email"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-4","title":"Offer Letter Drafting Assistant","prompt":"You are an HR operations expert with deep experience in compensation structuring. Draft a formal but personable offer letter for a Marketing Director joining a 200-person e-commerce company. Include the following details: base salary of $115,000 per year, annual performance bonus target of 15%, 20 days PTO plus company holidays, remote-first work arrangement with quarterly in-person team weeks, standard benefits (health, dental, vision, 401k with 4% match), an equity grant of 7,500 RSUs vesting over 4 years with a 1-year cliff, and a start date to be confirmed within 14 days. The letter should feel welcoming and reflect genuine excitement about the hire — not read like a legal document. End with clear instructions on how to accept the offer by countersigning.","tags":["hr","hiring","compensation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-5","title":"30-60-90 Day Onboarding Plan","prompt":"You are a talent development consultant specializing in leadership onboarding. Create a detailed 30-60-90 day onboarding plan for a newly hired VP of Sales joining a B2B software company with $15M ARR and a 12-person sales team. Structure the plan in three phases: Days 1–30 (listen, learn, and build relationships — include specific meetings with key stakeholders, CRM audit, and pipeline review), Days 31–60 (diagnose gaps and form hypotheses — include analysis of win/loss rates, territory structure review, and identifying one quick win), and Days 61–90 (begin executing — include one process improvement initiative, updated forecast methodology, and first leadership team presentation). For each phase, list 5–7 concrete action items, success metrics, and the primary outcome expected by the end of each phase.","tags":["hr","onboarding","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-6","title":"Sourcing Strategy for Hard-to-Fill Roles","prompt":"You are a talent acquisition strategist who has filled technical roles at competitive companies without relying on recruiters. Develop a 4-week active sourcing strategy to find and attract a Principal Data Engineer in a market where the role has been open for 60 days with no quality applicants from traditional job boards. The strategy must include: 3 non-traditional sourcing channels (such as open-source contributor databases, conference speaker lists, and Slack communities), a personalized outreach message template for LinkedIn and email that highlights the technical challenge of the role rather than perks, a referral incentive program design for existing engineering staff, a strategy for re-engaging silver-medalist candidates from prior hiring cycles, and a weekly activity target (20 outreach messages, 5 referral conversations) to hold the hiring team accountable.","tags":["hr","recruiting","talent-acquisition"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-7","title":"Compensation Benchmarking Analysis","prompt":"You are a total rewards consultant with expertise in technology sector compensation. Prepare a compensation benchmarking analysis summary for a Director of Engineering role at a Series C startup based in Austin, Texas with 300 employees. Pull from market context for roles at comparable stage companies (Series B–D, 150–500 employees). The analysis should include: the typical base salary range at P25, P50, and P75 percentiles, typical equity grant size (percentage or dollar value at grant), cash bonus structures, and how the total compensation compares to public tech company offers for the same level. Conclude with a 3-point recommendation on how the company should position its offer to be competitive without overpaying in the current funding environment. Clearly note any assumptions made about the data.","tags":["hr","compensation","benchmarking"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-8","title":"Exit Interview Question Framework","prompt":"You are an organizational psychologist specializing in employee retention and culture diagnostics. Design a structured exit interview framework for a 400-person retail technology company that has experienced 22% voluntary turnover in the past 12 months. The framework should include 12 questions that uncover the true reasons for departure — not the polished version candidates give when they want a good reference. Include questions that probe: the specific trigger moment that started their job search, their manager relationship quality, feelings about career progression and compensation fairness, what the company could have done differently in the last 6 months, and where they are going (role type, company size, industry). Add interviewer guidance notes for each question explaining how to probe deeper without leading the respondent.","tags":["hr","retention","culture"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-9","title":"Job Leveling Framework Creator","prompt":"You are an HR architect with expertise in compensation and career progression systems. Design a 6-level job leveling framework for a software engineering track at a 250-person SaaS company preparing for its first formal compensation review cycle. For each level (L1 Engineer through L6 Distinguished Engineer), define: a one-paragraph scope of impact statement, 4 core competencies with behavioral descriptions, the expected degree of autonomy and leadership, and a compensation band in base salary with specific dollar ranges appropriate for a mid-market US tech company. The framework should be rigorous enough to prevent title inflation and clear enough that an engineer can self-assess their level without ambiguity. Note any special considerations for the transition from individual contributor (L4) to staff-level (L5) work.","tags":["hr","career-development","compensation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-10","title":"Diversity Hiring Audit Memo","prompt":"You are a DEI strategy consultant with a background in organizational data analysis. Write an internal memo for a 500-person professional services firm whose engineering and senior leadership ranks are less than 15% women and less than 10% underrepresented minorities. The memo should: open with a data-grounded framing of the business case for representation (not just the moral one), identify the top 3 points in the hiring funnel where underrepresented candidates drop off (such as job description language, resume screening, and final-round offer acceptance), recommend 5 specific evidence-based interventions with an estimated effort level (low/medium/high) and expected timeline for each, and propose a 12-month measurement framework with 3 leading indicators. Avoid performative language — this memo is designed to create systemic change, not optics.","tags":["hr","dei","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // ── HR: Management & Employee Relations (b-11 to b-20) ──────────────────

  {"id":"b-11","title":"Performance Improvement Plan Writer","prompt":"You are an experienced HR business partner with expertise in performance management documentation. Draft a formal Performance Improvement Plan (PIP) for a mid-level Account Executive at a 150-person B2B SaaS company who has missed quota for three consecutive quarters (achieving 48%, 61%, and 55% of target respectively) and has received two prior informal coaching sessions that did not result in sustained improvement. The PIP should include: a factual, non-punitive description of the performance gap with specific metrics, 4 clearly measurable goals to be achieved within 60 days (minimum 70% of monthly quota, completing 2 training modules, improving CRM hygiene score to 90%), a weekly check-in cadence with the direct manager, consequences if goals are not met, and the employee's right to respond. Use a professional tone that is firm but not adversarial.","tags":["hr","performance-management","documentation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-12","title":"Annual Performance Review Template","prompt":"You are a talent management specialist who designs performance systems for high-growth companies. Build a complete annual performance review template for a manager-level employee (people manager with 3–8 direct reports) at a technology company. The template should include four sections: (1) Goal Achievement — structured space to assess 3–5 pre-set goals with a 1–5 rating scale and written evidence prompts, (2) Core Competencies — assessment of 6 competencies including people leadership, strategic thinking, cross-functional collaboration, communication, execution, and inclusion, each with behavioral anchors at each rating level, (3) Manager-Specific Assessment — team retention rate, team engagement score, direct report development, and feedback quality, and (4) Development Planning — a forward-looking section with one stretch goal, one skill to build, and one relationship to deepen in the next year. Include manager completion guidance at the top.","tags":["hr","performance-management","templates"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-13","title":"Difficult Feedback Conversation Script","prompt":"You are an executive coach who helps managers navigate high-stakes conversations. Help me prepare a script for delivering difficult feedback to a senior software engineer who consistently interrupts colleagues in meetings, frequently dismisses junior engineers' ideas in code reviews, and has created a dynamic where two team members have started avoiding collaboration with them. The engineer is technically exceptional and a high performer by output metrics. I need a script that: opens with a specific, non-judgmental observation, describes the observable impact on the team without attacking character, creates space for the engineer to respond, presents a clear behavioral expectation going forward, and ends with a collaborative commitment to improvement. Also provide 3 likely pushback responses and how I should address each one constructively.","tags":["hr","feedback","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-14","title":"Employee Recognition Program Design","prompt":"You are an HR culture specialist with expertise in intrinsic motivation and retention. Design a structured employee recognition program for a 300-person hybrid-remote financial services technology company where an engagement survey showed only 34% of employees feel their contributions are adequately recognized. The program must include: a peer recognition channel (not just top-down), a monthly spotlight with meaningful criteria, a manager toolkit with 5 specific recognition behaviors and scripts, a quarterly values-based award with a nomination and selection process, and a low-cost high-impact anniversary milestone system. Budget assumption: $150 per employee per year. Include rollout timeline, communication plan, and the 3 metrics you would track in the first 6 months to measure program effectiveness.","tags":["hr","culture","retention"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-15","title":"Manager Effectiveness Survey Design","prompt":"You are an organizational psychologist specializing in 360-degree feedback systems. Design a manager effectiveness survey for a Series D technology company (450 employees, 60 people managers) that will be administered to direct reports twice per year. Create 18 questions across 5 dimensions: Clarity and Direction (4 questions), Coaching and Development (4 questions), Psychological Safety (3 questions), Recognition and Feedback (4 questions), and Team Effectiveness (3 questions). For each question, write the exact survey item on a 5-point Likert scale from Strongly Disagree to Strongly Agree, and note the specific management behavior it is designed to measure. Include 2 open-ended questions at the end. Provide guidance on what score thresholds should trigger mandatory manager coaching conversations.","tags":["hr","management","feedback"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-16","title":"Workplace Conflict Resolution Framework","prompt":"You are a certified mediator and HR conflict specialist. Outline a step-by-step conflict resolution process for two senior managers — Head of Product and Head of Engineering — at a 200-person SaaS company who have an escalating interpersonal conflict rooted in repeated public disagreements over roadmap prioritization, which is now affecting team morale in both departments. The framework should include: an initial triage step to determine whether this is a style conflict or a structural problem, a facilitated conversation protocol with specific opening questions, a structured interests-versus-positions exploration, a documented agreement template with specific behavioral and process commitments, and a 30-day follow-up mechanism to ensure resolution holds. Also flag the 2 warning signs that would indicate the conflict has escalated beyond peer mediation and requires executive or legal involvement.","tags":["hr","conflict-resolution","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-17","title":"Remote Team Engagement Plan","prompt":"You are a future-of-work consultant specializing in distributed team culture. Create a 90-day engagement plan for a fully remote team of 18 engineers and designers spread across 4 time zones (US Eastern, US Pacific, UK, and Poland) whose latest engagement survey showed scores of 3.1 out of 5, with lowest scores in 'sense of belonging' and 'visibility of my work.' The plan should include: a weekly rhythm redesign with suggestions on what meetings to cut and what async rituals to add, a virtual 'work in public' practice that increases visibility without surveillance, one monthly touchpoint that builds genuine human connection (not forced fun), a quarterly virtual offsite structure with a 4-hour time budget, and a manager communication cadence that ensures no team member goes more than 72 hours without a meaningful check-in. Provide specific tools such as Loom, Donut, or Notion where relevant.","tags":["hr","remote-work","engagement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-18","title":"Promotion Calibration Brief","prompt":"You are a senior HRBP facilitating a promotion calibration session for a 350-person technology company. Write a calibration brief to help 8 functional leaders align on promotion standards for the upcoming cycle, where 22 employees have been nominated for promotion and the company needs to make decisions within a $280,000 total incremental compensation budget. The brief should include: a reminder of the promotion philosophy (promote on demonstrated performance at the next level, not potential alone), a calibration scenario with 3 hypothetical employee profiles at different readiness levels for managers to discuss and align on before reviewing real nominations, a structured decision matrix with 4 criteria and weighting, a process for handling cases where a manager's assessment differs significantly from peer or stakeholder input, and language for communicating both promotion decisions and 'not yet' decisions to employees.","tags":["hr","performance-management","compensation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-19","title":"Reduction in Force Communication Plan","prompt":"You are a seasoned HR executive with experience navigating workforce reductions at technology companies. Develop a communication plan for a 15% reduction in force (55 employees) at a 370-person B2B software company that is restructuring after missing revenue targets by 25% in the prior fiscal year. The plan must cover: Day 0 notification day with a timeline of events from 7am to end of day, manager briefing script, individual notification conversation guide, and IT/security off-boarding steps; Day 0 remaining-employee communication including all-hands talking points, a Slack message from the CEO, and a FAQ document covering questions about job security, severance, and company future; and Week 1 with a team re-integration communication for managers and a 30-day morale recovery checklist. Include explicit guidance on what NOT to say to avoid legal exposure or employee backlash.","tags":["hr","workforce-reduction","communications"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-20","title":"Hybrid Work Policy Drafting","prompt":"You are an employment law-aware HR writer creating clear, enforceable, and employee-friendly policy documents. Draft a hybrid work policy for a 280-person professional services firm that transitioned to hybrid work in 2022 and now needs a formal policy to address inconsistent manager application of remote work privileges, multiple employee grievances about perceived unfairness, and upcoming lease decisions for two office locations. The policy should include: eligibility criteria (role types, tenure, performance standing), approved remote days per week and blackout periods such as onboarding weeks and client-visit weeks, equipment and expense reimbursement terms, core hours for synchronous availability, the process for requesting exceptions, and manager obligations for equitable application. Written in plain English at an eighth-grade reading level. Note: advise consulting legal counsel before publishing.","tags":["hr","policy","remote-work"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // ── Finance & Payroll (b-21 to b-30) ────────────────────────────────────

  {"id":"b-21","title":"Monthly Board Financial Narrative","prompt":"You are a CFO preparing the monthly financial narrative for the board of directors of a Series C SaaS company ($28M ARR, 260 employees). Write the narrative commentary for a month where: ARR grew 2.1% MoM (ahead of 1.8% plan), gross margin came in at 71% (down from 73% the prior month due to infrastructure cost increases), net revenue retention was 108% (consistent with prior month), operating expenses were 4% over budget due to accelerated engineering headcount, and free cash flow was negative $1.2M against a plan of negative $0.9M. The commentary should explain the variances, contextualize them within the full-year plan, identify the top 2 financial risks for the coming quarter, and propose 3 specific management actions. Write at an executive level — assume the reader is a sophisticated investor.","tags":["finance","reporting","saas-metrics"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-22","title":"Budget Variance Analysis Explainer","prompt":"You are a financial analyst at a mid-market manufacturing company preparing the Q3 budget variance report for the CFO and division heads. Write a structured variance analysis for a division that came in $2.4M over its $14.8M operating expense budget this quarter. The key variances are: raw material costs +$800K driven by commodity price increases, overtime labor +$600K due to a 3-week line downtime for equipment repair, logistics +$450K from fuel surcharges, and marketing +$350K from a trade show campaign approved mid-quarter. The remaining $200K is in miscellaneous overruns across departments. The report should: explain each variance clearly for a non-finance executive audience, separate controllable from non-controllable variances, provide a revised full-year forecast with these trends factored in, and recommend 3 cost mitigation actions for Q4.","tags":["finance","budgeting","reporting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-23","title":"SaaS Unit Economics Deep Dive","prompt":"You are a SaaS finance expert preparing an investor-ready unit economics analysis for a Series B B2B SaaS company. The company has the following metrics: average contract value of $24,000 per year, average sales cycle of 65 days, blended CAC of $18,000 (60% sales, 40% marketing), gross margin of 74%, average customer lifetime of 4.2 years, monthly gross churn of 1.1%, and NRR of 112%. Calculate and explain: CAC payback period in months, LTV using both simple and discounted cash flow methods, LTV:CAC ratio, the implied unit economics at scale, and how these metrics compare to SaaS benchmarks for a company at this stage. Then identify the 2 most impactful levers management could pull to improve LTV:CAC by 20% within 12 months, with specific recommendations and estimated impact.","tags":["finance","saas-metrics","unit-economics"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-24","title":"Annual Budget Build Framework","prompt":"You are a VP of Finance facilitating the annual budget process for a 400-person technology company entering its fiscal year planning cycle in October. Design a complete budget build framework — from kickoff to board approval — that can be executed over 8 weeks. Include: a week-by-week timeline with owners and deliverables, a department budget submission template with required line items (headcount plan, external spend, capex, and key assumptions), instructions for the bottoms-up headcount planning process including how to model for open roles versus backfills, a process for consolidating department submissions into a company P&L, guidance on scenario planning (base case, bear case, bull case), and a checklist for the CFO review and board presentation. Note common failure modes at each stage and how to avoid them.","tags":["finance","budgeting","planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-25","title":"Startup Cash Flow Forecast Walkthrough","prompt":"You are a CFO coach helping a first-time startup founder understand their company's financial position. Explain the 13-week rolling cash flow forecast for a pre-revenue Series A startup that has $2.1M in the bank, is burning $320,000 per month in operating expenses, has a $750,000 receivable expected in week 6 from their first enterprise customer, and expects to close a $4M venture debt facility in week 10. Walk through: the current runway calculation, how the receivable and debt facility change the cash position week by week, what the ending cash balance looks like at week 13, what assumptions carry the most risk, and what specific actions the founder should take right now if the enterprise receivable slips by 3 weeks. Use clear, jargon-free language. Include a simplified week-by-week table showing opening balance, inflows, outflows, and closing balance.","tags":["finance","cash-flow","startups"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-26","title":"Payroll Discrepancy Investigation Protocol","prompt":"You are a payroll operations director at a 600-person company with employees in 8 US states, running payroll biweekly through ADP Workforce Now. Write a structured investigation protocol for resolving a payroll discrepancy where 14 employees in the Texas and Arizona offices received incorrect net pay in the most recent pay cycle — some overpaid by $200–$800 and others underpaid by similar amounts — believed to be caused by an incorrect state tax table update. The protocol should include: immediate containment actions within the first 4 hours of discovery, a root cause investigation checklist, communication templates for employees who were underpaid (requiring correction within 24 hours) versus overpaid (requiring recovery through next payroll), documentation requirements for the audit trail, and a corrective action plan to prevent recurrence. Include payroll compliance notes for Texas and Arizona specifically.","tags":["finance","payroll","compliance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-27","title":"Financial Model Assumptions Documentation","prompt":"You are a senior FP&A analyst at a retail technology company preparing a financial model for a $5M investment decision to launch a new product line. Write the assumptions documentation that accompanies the 3-year financial model. The document should clearly articulate and justify: revenue assumptions (average selling price of $85, Year 1 unit sales of 40,000 growing 45% in Year 2 and 30% in Year 3, and a 12% channel returns rate), cost of goods assumptions (gross margin of 52% in Year 1 improving to 58% by Year 3 as volume scales), headcount plan (4 FTE in Year 1, 9 FTE by end of Year 2), marketing spend (25% of revenue in Year 1 declining to 18% by Year 3), and working capital assumptions (60-day inventory, 45-day accounts receivable). For each assumption, state the source, the key risk to that assumption, and the sensitivity impact (e.g., a 5% change in gross margin impacts Year 3 EBITDA by what amount).","tags":["finance","financial-modeling","planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-28","title":"Vendor Payment Terms Negotiation Brief","prompt":"You are a treasury manager at a growing consumer goods company that currently pays its top 5 suppliers on Net 30 terms and wants to negotiate extended payment terms of Net 60 or Net 75 to improve cash flow by approximately $1.8M. Prepare a negotiation brief for a conversation with the CFO of your largest supplier (a $120M annual spend relationship). The brief should include: the business rationale from both perspectives, 3 value-exchange proposals (extended terms in exchange for volume commitment, early-pay discount option, or supply chain financing enrollment), the minimum acceptable outcome, your BATNA if they decline, key objections they are likely to raise and prepared responses, and any relationship considerations that should influence your approach. Include specific dollar amounts and percentages throughout.","tags":["finance","procurement","negotiation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-29","title":"Modern Expense Policy Redesign","prompt":"You are a finance operations consultant helping a 350-person professional services firm redesign its outdated employee expense policy. The current policy was written in 2016, has 40+ pages of rules, requires paper receipts for everything over $25, and has a 45-day average reimbursement cycle — resulting in widespread employee complaints and significant finance team processing time. Design a modern, trust-based expense policy that: sets clear per-category spending limits for common expense types (meals, travel, client entertainment, home office), eliminates receipts for transactions under $75, defines an auto-approval threshold, specifies audit sampling methodology, and outlines consequences for misuse. Include a rollout communication plan and a FAQ document. The policy should fit on 2 pages and be readable by any employee — not just accountants.","tags":["finance","policy","operations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-30","title":"Series B Fundraising Readiness Checklist","prompt":"You are a CFO advisor who has helped 20+ companies raise institutional venture capital rounds. Create a Series B fundraising readiness checklist for a B2B SaaS company with $8M ARR, growing 85% year-over-year, targeting a $25–35M raise. The checklist should cover 7 areas: (1) financial data room documents and their specific format requirements, (2) metrics package with the 15 SaaS metrics investors will expect to see with period-over-period history, (3) cap table cleanliness and common issues to resolve before raising, (4) board governance and minute hygiene, (5) customer contract review for standard commercial terms including change of control and assignment clauses, (6) technical and IP audit preparation, and (7) founder reference preparation. For each area, rate the typical effort level (1–3 weeks, 3–6 weeks, or 6+ weeks) so the team can build a realistic prep timeline.","tags":["finance","fundraising","startups"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  // ── Strategy & Planning (b-31 to b-45) ──────────────────────────────────

  {"id":"b-31","title":"Competitive Landscape Analysis","prompt":"You are a strategy consultant with expertise in competitive intelligence for B2B software markets. Conduct a structured competitive landscape analysis for a project management software company that competes primarily with Asana, Monday.com, and Notion for the mid-market segment (50–500 employee companies). The analysis should include: a feature comparison matrix across 8 dimensions (task management, workflow automation, reporting, integrations, mobile experience, collaboration, pricing model, and enterprise readiness), a positioning map plotting each competitor on two axes of ease of use versus depth of functionality, a SWOT analysis of the market leader's position, identification of the top 2 underserved customer jobs-to-be-done in the current market, and a strategic recommendation for a differentiation angle that is defensible over 18–24 months. Base the analysis on publicly available information and note any gaps in intelligence.","tags":["strategy","competitive-analysis","market-research"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-32","title":"OKR Planning Workshop Design","prompt":"You are a management consultant specializing in organizational goal-setting frameworks who has facilitated OKR implementations at 30+ companies. Design a 3-hour OKR planning workshop for a 120-person SaaS company that is moving from annual MBO-style goal setting to quarterly OKRs for the first time, starting with their Q1 planning cycle. The workshop design should include: a 20-minute opening session on OKR philosophy and common failure modes to avoid with specific examples, a 60-minute exercise for leadership to draft company-level OKRs with 3 worked examples of strong versus weak key results in a SaaS context, a 45-minute breakout for department teams to draft team-level OKRs and check for vertical alignment, a 30-minute cross-functional dependency mapping exercise, and 15 minutes for commitment and next steps. Include facilitator notes, slide prompts, and a template teams can use during the session.","tags":["strategy","planning","okrs"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-33","title":"UK Market Entry Strategy Brief","prompt":"You are a strategy director at a US-based HR technology company with $40M ARR preparing a market entry brief for expanding into the UK market. The company has 3 enterprise customers in the UK from inbound demand but has never invested resources there. Write a structured market entry brief covering: UK market sizing for the HR tech segment (TAM, SAM, and the realistic serviceable obtainable market in Year 1–2), the 3 most significant localization requirements (payroll legislation compliance, GDPR data residency, and British employment law nuances), a comparison of 3 go-to-market entry modes (direct sales team, channel partnership, and acquisition), a recommended entry mode with rationale, a 12-month build plan with key milestones, and the 3 critical success factors that will determine whether the expansion achieves its $3M ARR Year 1 target.","tags":["strategy","market-entry","international"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-34","title":"Annual Strategic Planning Offsite Agenda","prompt":"You are a chief of staff facilitating a 2-day annual strategic planning offsite for a 15-person executive leadership team at a $200M revenue professional services company. Design the complete offsite agenda, including pre-read materials and post-offsite follow-up structure. Day 1 should focus on external orientation: market trends, competitive pressures, and customer voice, with specific session types and time blocks. Day 2 should focus on internal strategy setting: portfolio review, resource allocation decisions, and 3-year financial aspirations. For each session, specify: the objective, the format (presentation, working session, debate), the pre-read required, and the decision or output expected by end of session. The offsite must end with a concrete 12-month priority list with owners and a 30-day action plan. Include facilitation notes for the moderator.","tags":["strategy","planning","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-35","title":"Build vs Buy vs Partner Decision Framework","prompt":"You are a senior technology strategy advisor helping a 500-person logistics company decide how to add AI-powered route optimization to its platform. The company is evaluating three options: building the capability in-house (estimated 14 months and $2.2M), licensing an existing API-based solution from a specialist vendor ($180K per year, live in 8 weeks), or partnering with a logistics AI startup through a co-development arrangement. Apply a structured build vs buy vs partner framework that evaluates each option across 6 dimensions: time to market, total cost of ownership over 3 years, strategic control and IP ownership, vendor dependency risk, internal capability building value, and integration complexity. Present findings in a decision matrix, state a clear recommendation with primary rationale, and identify the 2 conditions under which the recommendation would change.","tags":["strategy","technology","decision-making"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-36","title":"Porter's Five Forces Industry Analysis","prompt":"You are a strategic analyst preparing an industry attractiveness assessment for a private equity firm evaluating an investment in a mid-size commercial printing company. Apply Porter's Five Forces framework to the commercial printing industry in North America. For each force, provide: a force intensity rating of Low, Medium, or High; 3–4 specific factors driving that rating; and an implication for business profitability. Forces to analyze: Threat of New Entrants, Bargaining Power of Suppliers, Bargaining Power of Buyers, Threat of Substitute Products, and Competitive Rivalry. Conclude with an overall industry attractiveness score on a 1–10 scale and a 2-paragraph strategic summary of what a company must do exceptionally well to build a defensible position in this industry. Base your analysis on publicly available industry data and label any assumptions clearly.","tags":["strategy","competitive-analysis","frameworks"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-37","title":"B2B Customer Segmentation Strategy","prompt":"You are a B2B marketing strategist specializing in customer segmentation for growth-stage technology companies. Design a customer segmentation framework for a $12M ARR project management software company that has 850 paying customers ranging from 5-person design agencies to 2,000-person enterprise technology companies, and is struggling with high churn in the under-50-employee segment. The framework should include: a recommended segmentation methodology using firmographic, behavioral, and needs-based dimensions; 4–5 clearly defined customer segments with names, profiles, and typical ACV; an analysis of which segments likely have the best LTV:CAC ratio and why; a recommendation on which segments to prioritize for growth versus which to exit; and specific product, sales, and marketing implications. Provide example customer persona cards for the top 2 priority segments.","tags":["strategy","marketing","customer-success"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-38","title":"SaaS Business Model Transition Analysis","prompt":"You are a business model innovation consultant working with a traditional B2B software company that sells perpetual on-premise licenses (average deal size $85,000, 3-year maintenance contracts at 20% annually) and is under pressure from cloud-native competitors offering subscription pricing. Analyze 3 business model transition paths: (1) full migration to SaaS subscription, (2) hybrid model offering both perpetual and subscription, and (3) consumption-based pricing. For each model, analyze: the financial impact on revenue recognition in Years 1–3 with specific percentage change estimates, the sales motion change required, the customer retention implications, and the competitive positioning effect. Recommend the optimal transition model with a phased implementation plan. Include a specific warning about the revenue dip companies face during this transition and how to manage it with investors.","tags":["strategy","business-model","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-39","title":"Executive KPI Dashboard Design","prompt":"You are a business intelligence strategist designing the executive KPI dashboard for a 300-person e-commerce company that sells direct-to-consumer health and wellness products. The CEO wants a single-page executive dashboard that can be reviewed in 10 minutes every Monday morning. Design the dashboard structure including: the 5 revenue and growth KPIs with specific metric names, measurement frequency, and target-setting methodology; the 4 operational health KPIs covering fulfillment, inventory, and customer service; the 3 customer KPIs (acquisition cost, repeat purchase rate, and NPS); and the 2 financial KPIs (gross margin and operating cash flow). For each KPI, define the exact formula, the data source, the weekly and monthly target ranges, and the alert threshold that triggers executive attention. Include a visual layout sketch description and guidance on color-coding for above- and below-target performance.","tags":["strategy","analytics","reporting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-40","title":"SaaS Pricing Architecture Overhaul","prompt":"You are a pricing strategy consultant who has redesigned pricing for 15 SaaS companies. Evaluate and redesign the pricing strategy for a B2B analytics SaaS company currently offering 3 flat-rate tiers at $99/month, $299/month, and $799/month. The company has 1,200 customers, with 70% on the $99 plan, a 40% annual churn rate on that plan, and an NPS of 67 among customers on the $299 and $799 plans. Propose a new pricing architecture that: shifts to a value metric aligned with customer success (suggest the right metric and explain why), creates better land-and-expand economics, reduces churn risk from price sensitivity, and improves revenue per customer by at least 25% over 12 months without losing more than 10% of the existing customer base. Include specific price points, package names, and a migration strategy for existing customers.","tags":["strategy","pricing","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-41","title":"Strategic Partnership Memo for Board","prompt":"You are a VP of Business Development preparing a strategic partnership memo for board review. The company is a $25M ARR legal technology platform exploring a distribution partnership with a Big Four accounting firm that has 12,000 commercial clients in the US — 40% of which have legal technology needs that align directly with the platform's capabilities. Write the memo covering: the strategic rationale for the partnership (why now, why this partner), the proposed partnership structure (co-selling, white-label, or referral), the commercial terms framework including revenue share range, minimum commitments, and exclusivity considerations, the operational requirements to make the partnership work, the risk factors including channel conflict with the direct sales team, and the success criteria for a 12-month pilot phase. Keep the memo under 1,200 words.","tags":["strategy","partnerships","business-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-42","title":"Product Roadmap Prioritization Scoring Model","prompt":"You are a head of product strategy helping a Series B product team of 35 people (7 product managers and 28 engineers) that has a backlog of 140 feature requests and needs a rigorous framework for quarterly roadmap prioritization. Design a scoring and prioritization model that accounts for: strategic alignment (weight 30%), estimated revenue impact (weight 25%), customer demand signal strength (weight 20%), development effort (weight 15%), and technical risk (weight 10%). For each dimension, provide a 1–5 scoring rubric with behavioral anchors so different PMs score consistently. Walk through a worked example scoring 3 hypothetical features — a large enterprise integration, a self-serve onboarding improvement, and a new reporting module — and show how the model would rank them. Include guidance on when a feature should bypass the model due to strategic override.","tags":["strategy","product","planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-43","title":"Digital Transformation Roadmap for Insurance","prompt":"You are a digital transformation advisor helping a 1,200-person regional insurance company whose current technology stack includes a 20-year-old policy management system, paper-based claims processing, and no mobile customer experience. The CEO has committed to a 3-year digital transformation with a $12M technology budget. Build a phased transformation roadmap with Year 1 (foundational), Year 2 (acceleration), and Year 3 (optimization) phases. For each year, define: the 3–4 priority initiatives with business outcome goals, the required technology investments, the organizational capability changes needed, and the success metrics. Year 1 must focus on the highest-ROI quick wins that demonstrate momentum to skeptical board members. Flag the top 3 organizational resistance points and change management strategies for each.","tags":["strategy","digital-transformation","technology"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-44","title":"Scenario Planning Workshop for Manufacturers","prompt":"You are a strategic foresight consultant facilitating a scenario planning workshop for the leadership team of a 600-person global manufacturing company concerned about supply chain concentration risk, energy price volatility, and emerging market demand shifts. Design a 4-hour scenario planning workshop that produces 3 distinct future scenarios the company may face in 5 years. The design should include: a 45-minute environmental scanning exercise to identify the most uncertain and impactful external forces, a structured scenario building methodology, descriptions of the 3 resulting scenarios with names, key characteristics, and probability assessments, a strategy stress-testing exercise where participants evaluate their current strategy against each scenario, and a 'no-regrets moves' identification exercise. Provide all facilitation materials including flip chart prompts and voting mechanisms.","tags":["strategy","planning","risk-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-45","title":"M&A Target Evaluation Scorecard","prompt":"You are a corporate development director at a $150M revenue healthcare technology company with a mandate to make 1–2 acquisitions per year in the $5–20M revenue range to accelerate product line expansion. Build an acquisition target evaluation framework that can be used to consistently score and compare potential targets. The framework should include: a strategic fit scorecard with 4 criteria (product adjacency, customer overlap, technology leverage, and market positioning), a financial attractiveness scorecard with 4 criteria (revenue quality, growth rate, gross margin profile, and path to profitability), an integration risk assessment with 3 criteria (cultural fit, technology compatibility, and team retention risk), and a combined scoring methodology weighting strategic fit at 50%, financial attractiveness at 30%, and integration risk at 20%. Provide example scoring for a hypothetical target company. Include the 5 deal-breaker conditions that would disqualify a target regardless of score.","tags":["strategy","mergers-acquisitions","corporate-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // ── Sales & Negotiation (b-46 to b-60) ──────────────────────────────────

  {"id":"b-46","title":"Enterprise Sales Outreach Sequence","prompt":"You are a senior enterprise sales strategist specializing in outbound prospecting for B2B SaaS companies. Write a 5-touch outreach sequence targeting the VP of Operations at mid-size logistics companies (500–2,000 employees) for a warehouse management software product. The sequence spans 14 business days: Touch 1 on Day 1 is a personalized cold email referencing a specific industry pain around inventory accuracy in the warehouse automation era; Touch 2 on Day 3 is a LinkedIn connection request with a value-first note; Touch 3 on Day 5 is a social proof email with a one-sentence case study result from a similar company; Touch 4 on Day 9 is a pattern-interrupt email with a direct, short ask; and Touch 5 on Day 14 is a breakup email with a low-friction final CTA. Each touch should be under 150 words, reference the specific buyer persona, and never lead with product features. Include a note on personalization variables for each touch.","tags":["sales","outbound","email"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-47","title":"CISO Discovery Call Question Framework","prompt":"You are an enterprise sales trainer who has developed discovery methodologies for Fortune 500 sales organizations. Build a discovery call framework for a cybersecurity software sales rep meeting with a CISO at a 1,000-person financial services firm for the first time. The framework should structure 45 minutes as follows: 5-minute rapport and agenda-setting opener; 20 minutes of situation and problem discovery questions covering current security stack, recent incidents, team structure, budget cycle, and compliance requirements (provide 8 questions); 10 minutes of implication and consequence exploration (provide 4 questions that help the CISO articulate the cost of inaction); 7 minutes of vision and success criteria questions (provide 3 questions); and 3 minutes for next steps. Include transition phrases between each section and note which questions are most likely to reveal genuine buying intent versus polite engagement.","tags":["sales","discovery","enterprise"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-48","title":"Enterprise Software Sales Proposal","prompt":"You are a proposals specialist who has written winning RFP responses and custom proposals for a B2B technology company with deal sizes of $100K–$2M. Write a structured sales proposal for a 3-year enterprise contract for an HR software platform with a total contract value of $420,000 ($140,000 per year for 350 users). The proposal is responding to a specific pain expressed in discovery: the prospect's HR team spends 12 hours per week on manual reporting, has 22% employee data errors from disconnected systems, and wants a self-service manager portal before their Q3 open enrollment cycle. The proposal should include: an executive summary that leads with the prospect's stated outcomes not product features, a solution section that maps 4 specific capabilities to 3 stated pain points, an ROI analysis showing payback period, clear pricing with no ambiguity, a 90-day implementation timeline, 3 relevant customer references with one-line results, and a call to action with a decision deadline.","tags":["sales","proposals","enterprise"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-49","title":"Sales Objection Handling Playbook","prompt":"You are a sales enablement director building an objection handling playbook for a 25-person enterprise SaaS sales team selling a $50K–$200K annual contract supply chain visibility platform. Build responses for the 8 most common objections: (1) 'We already have a solution for this'; (2) 'Your price is too high'; (3) 'We're not ready to make this decision right now'; (4) 'We need to get IT involved and they'll never approve this'; (5) 'Can you match what the competitor is offering?'; (6) 'I need to think about it'; (7) 'We're going through a budget freeze'; and (8) 'Can you do a pilot first before we commit?' For each objection: write the ideal response (3–5 sentences), the psychological insight driving the objection, a follow-up question to further qualify, and a note on when the objection is a genuine deal-blocker versus a negotiating tactic.","tags":["sales","objection-handling","enablement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-50","title":"SaaS Renewal Negotiation Strategy","prompt":"You are a contract negotiation advisor helping a $30M ARR SaaS company's sales director prepare for a renewal negotiation with their largest customer — a 3,000-person manufacturing company paying $320,000 per year. The customer has sent signals that they want a 20% price reduction at renewal (6 weeks away) and is referencing a competing quote. The company's cost to serve this customer is $85,000 per year and they cannot afford to lose the account. Develop a negotiation strategy that includes: BATNA analysis for both sides, the ideal outcome and walk-away point with specific dollar ranges, a concession strategy covering what to give and what to hold in what order, 3 value-add alternatives to pure price reduction (such as expanded seats, success services, or multi-year lock-in), language for the opening of the negotiation conversation, and red flags that indicate the customer is genuinely likely to churn versus just negotiating.","tags":["sales","negotiation","account-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-51","title":"Enterprise Sales Forecast Methodology","prompt":"You are a VP of Sales building a reliable forecasting methodology for a 30-person enterprise sales team at a $20M ARR B2B software company that currently has low forecast accuracy (±35% variance to close). Design a stage-based forecast methodology that reduces forecast variance to under 15% within two quarters. The methodology should include: a revised pipeline stage definition with specific entry and exit criteria, a weighted pipeline calculation model, a methodology for call commits (what evidence a rep must provide to include a deal in a commit forecast), a weekly forecast review cadence and meeting structure, a simple deal inspection framework for managers (5 diagnostic questions per deal), and a way to track and improve individual rep forecast accuracy over time. Include a worked example showing how a $1.8M quarter forecast would be built from a pipeline of 22 open opportunities.","tags":["sales","forecasting","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-52","title":"Inside Sales Compensation Plan Design","prompt":"You are a sales compensation consultant designing an incentive plan for a 20-person inside sales team at a B2B SaaS company with ACV of $15,000–$45,000. The current plan has low attainment (only 45% of reps hit quota last year) and the company suspects the plan is over-complex and misaligned with the most valuable behaviors. Design a new compensation plan that includes: a recommended on-target earnings structure by role (SDR, AE, and Senior AE) with base/variable split, an annual quota setting methodology with a recommended ramp schedule for new hires, an accelerator structure above 100% that is genuinely motivating, a specific SPiFF design for 2 strategic products that need volume this quarter, a plan document that fits on one page per role, and a manager's guide for quota conversations. Explain your reasoning for each design decision and note the 3 most common compensation plan failure modes you are deliberately avoiding.","tags":["sales","compensation","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-53","title":"Customer Case Study Interview Guide","prompt":"You are a customer marketing manager creating a library of high-impact customer case studies for a B2B HR technology platform. Write a complete case study interview guide for a 45-minute customer interview with the Head of HR at a 600-person healthcare company who has been using the platform for 18 months. The guide should include: 5 background questions that establish the customer's context before implementation (company size, HR team structure, and core pain points), 6 implementation and adoption questions that draw out specific challenges and how they were resolved, 5 results questions designed to extract quantifiable outcomes (time saved, error reduction, cost avoidance, and employee satisfaction scores), and 3 forward-looking questions for future expansion and advocacy potential. Include interviewer guidance notes explaining how to probe for specific numbers when customers give vague answers, and a post-interview checklist for what to follow up on in writing.","tags":["sales","marketing","customer-success"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-54","title":"Customer Account Expansion Playbook","prompt":"You are a customer success and expansion sales expert designing an account expansion playbook for a cloud security SaaS company where 80% of revenue growth is expected to come from expanding within existing customers (current average ACV: $65,000, expansion potential: $130,000). Design a 12-month playbook for the CSM team to systematically identify and convert expansion opportunities. The playbook should include: a health score model with 5 indicators that predict expansion readiness (not just churn risk), a trigger-based expansion motion with 3 specific usage signals that should prompt an expansion conversation, an Executive Business Review template with an expansion narrative built in, a multi-threading strategy to reach economic buyers within existing accounts, objection handling for the 'expand within current budget' resistance, and a compensation model recommendation for CSMs expected to both retain and expand. Include example talking points for the transition from a success conversation to a commercial conversation.","tags":["sales","account-management","customer-success"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-55","title":"Win/Loss Analysis Program Design","prompt":"You are a sales analytics director designing a systematic win/loss analysis program for a 50-person B2B software sales organization that currently has no structured process for understanding why deals are won or lost. The company closes approximately 80 new deals per quarter and loses roughly 120 qualified opportunities. Design a program that includes: a post-deal survey instrument (8 questions for both won and lost deals, designed to be sent within 5 days of a decision), a quarterly win/loss interview guide for in-depth calls with 10 selected accounts, a tagging taxonomy for categorizing win/loss reasons (provide 5 primary categories and 3–4 subcategories each), a quarterly reporting template that translates raw data into strategic insights for product, sales, and marketing teams, and a governance model for who owns the program, who reviews outputs, and how findings are actioned. Include a note on how to achieve a 40%+ response rate on post-deal surveys.","tags":["sales","analytics","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-56","title":"Sales Enablement Content Audit","prompt":"You are a sales enablement manager conducting a content audit for a 40-person enterprise software sales team that has accumulated 300+ pieces of content over 3 years, most of which is outdated, hard to find, and not used by reps. Design a complete content audit process and governance framework. The audit process should include: a content inventory methodology covering how to tag and categorize existing assets; a usage and effectiveness scoring model combining CRM data, content platform analytics, and rep surveys; a decision framework for keep, update, or retire decisions; and a recommended content library structure aligned to buyer journey stage and deal size. The governance framework should include: a content creation approval process, a quarterly content review cadence, content ownership assignments by role, and a 'last reviewed' tagging system. Conclude with a prioritized list of the 10 content gaps most likely to impact win rates.","tags":["sales","enablement","content"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-57","title":"Channel Partner Program Design","prompt":"You are a channel strategy director designing a value-added reseller (VAR) program for a $18M ARR cybersecurity software company that wants 30% of revenue to come through channel partners within 24 months. Design a two-tier partner program (Authorized and Gold tiers) that includes: partner eligibility criteria for each tier, the economic model (margin structure, deal registration discounts, co-sell incentives), partner enablement requirements (certification, sales training, technical support access), co-marketing support (MDF allocation, co-branded content, lead sharing rules), a partner portal specification with the 5 most critical features, and a partner account manager coverage model. Include the 5 most common channel program failure modes (channel conflict, insufficient margins, poor MDF tracking) and the specific design decisions in your program that address each one.","tags":["sales","channel","partnerships"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-58","title":"Account-Based Territory Redesign","prompt":"You are a sales operations director redesigning the territory structure for a 35-rep enterprise sales team at a $45M ARR B2B data analytics company that sells to mid-market and enterprise companies (250–10,000 employees) across North America. The current territory design is based purely on geography and has created significant imbalance — some reps have 3x the addressable market of others. Redesign the territories using an account-based model. The redesign should include: the segmentation criteria for dividing accounts (industry vertical, employee count, and estimated ACV potential), a methodology for scoring and distributing approximately 12,000 named accounts across 35 territories, a fairness validation approach using total addressable revenue per territory, a process for grandfathering existing customer relationships, and a transition communication plan for reps who will lose accounts. Flag the top 3 political and morale risks of a territory rebalance and how to manage them.","tags":["sales","operations","planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-59","title":"Healthcare Procurement Counter-Proposal","prompt":"You are a senior procurement negotiator at a 2,000-person healthcare system preparing a counter-proposal for a software vendor's initial enterprise offer. The vendor's proposal is $680,000 for a 3-year EHR integration platform contract (Year 1: $200K, Year 2: $230K, Year 3: $250K) with Net 30 payment terms, no SLA credits, a 5% annual price escalator, and auto-renewal with 90-day cancellation notice. Your target is a fully executed contract at no more than $580,000 total. Write the counter-proposal covering: proposed revised pricing with justification referencing healthcare system budget constraints and multi-year commitment value, requested SLA terms with specific uptime requirements and credit structure, removal of the auto-escalator or replacement with a CPI cap, amended payment terms to Net 45, and a 6-month implementation support commitment at no additional charge. Frame the counter-proposal as a partnership pitch, not a cost-cutting demand.","tags":["sales","negotiation","procurement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-60","title":"Quarterly Business Review Presentation","prompt":"You are a strategic account manager preparing a Quarterly Business Review presentation for a Tier 1 customer — a 5,000-person retail company paying $280,000 per year for a supply chain analytics platform. The QBR is a 60-minute in-person meeting with the customer's VP of Supply Chain, Head of IT, and CFO. Build the complete presentation structure and talking points covering: a 5-minute executive summary slide with key achievements, current health score, and upcoming priorities; a 10-minute business outcome review showing platform-generated savings of $1.2M this quarter; a 10-minute adoption and usage review showing 78% active user rate versus 65% target; a 15-minute strategic roadmap discussion introducing 2 new capabilities relevant to their 2025 cost-reduction initiative; a 10-minute ROI and renewal discussion (contract up in 7 months, introduce 3-year renewal option); and 10 minutes for Q&A and next steps. Include slide notes and presenter guidance for each section.","tags":["sales","account-management","presentations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // ── Operations & Logistics (b-61 to b-75) ───────────────────────────────

  {"id":"b-61","title":"Order Fulfillment Process Improvement Workshop","prompt":"You are a lean operations consultant facilitating a process improvement workshop for the order fulfillment team at a 400-person e-commerce company experiencing a 12% order error rate and 3.2-day average order processing time against a target of 1.5 days. Design a 4-hour Value Stream Mapping workshop for 8 participants (warehouse manager, 2 team leads, 4 frontline workers, and 1 IT analyst). The workshop design should include: a 30-minute current state mapping exercise with specific facilitation instructions, a 45-minute waste identification exercise using the 8 wastes of lean with examples relevant to e-commerce fulfillment, a root cause analysis session using the 5-Why method for the top 2 identified problems, a future state mapping exercise, and a prioritized improvement action plan template. Provide all facilitation materials including sticky note prompts, timing guidance, and team engagement techniques.","tags":["operations","process-improvement","lean"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-62","title":"Customer Complaint SOP Writer","prompt":"You are an operations documentation specialist who writes SOPs for ISO 9001-certified manufacturing environments. Write a complete Standard Operating Procedure for the Customer Complaint Intake and Escalation Process at a 250-person consumer electronics company. The SOP should include: a purpose and scope statement, a roles and responsibilities table (Customer Support Agent, Support Team Lead, Quality Assurance Manager, and Product Engineering Liaison), a step-by-step process flow with 12–15 numbered steps covering complaint receipt through resolution and root cause logging, decision trees for escalation criteria (severity 1 vs. 2 vs. 3 classification), required documentation at each step, response time SLAs by severity level, and a revision history table. Write in clear, active-voice language at a level that can be followed by a newly hired customer support agent on their first day. Include a brief training quiz with 5 questions at the end.","tags":["operations","documentation","process"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-63","title":"Supply Chain Risk Assessment","prompt":"You are a supply chain risk management consultant conducting a risk assessment for an $80M consumer goods company that sources 70% of its components from 3 suppliers in a single geographic region. The assessment follows an event where a 6-week manufacturing shutdown at the primary supplier caused $4.2M in lost sales. Conduct a comprehensive supply chain risk assessment covering: a risk identification matrix across 5 categories (supplier concentration, geographic risk, logistics disruption, demand volatility, and regulatory/compliance risk), a risk rating methodology using likelihood times impact on a 1–5 scale applied to 10 specific risk scenarios, a heat map layout description for visualizing the risk portfolio, a mitigation strategy for the top 5 risks with estimated implementation cost and risk reduction potential, and a supply chain resilience scorecard the company can use to track improvement over the next 12 months.","tags":["operations","supply-chain","risk-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-64","title":"ERP System Selection RFP","prompt":"You are a procurement operations specialist designing a Request for Proposal process for a 600-person healthcare company selecting a new Enterprise Resource Planning system. Write a complete RFP document structure for a project with a budget of $1.5M implementation and $300K annual licensing. The RFP should include: a company background and project overview section, a detailed scope of work covering 8 required functional modules (finance, HR, procurement, inventory, manufacturing, sales, reporting, and integration layer), a 40-question vendor response questionnaire organized by category (company profile, product functionality, implementation methodology, references, pricing, and security/compliance), evaluation criteria with weightings (functionality 35%, implementation capability 25%, total cost of ownership 20%, vendor viability 15%, references 5%), commercial terms requirements, and a 10-week evaluation timeline. Include instructions for how vendors should format their responses to enable apples-to-apples comparison.","tags":["operations","procurement","vendor-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-65","title":"Distribution Center Layout Optimization","prompt":"You are an industrial engineering consultant specializing in warehouse and distribution center optimization. Conduct an analysis and present recommendations for optimizing the layout of a 45,000 square foot distribution center for an online grocery retailer that processes 2,800 orders per day and is experiencing pick time inefficiencies — current average pick rate is 85 units per hour against an industry benchmark of 120 units per hour. The analysis should cover: a slotting optimization strategy using ABC analysis methodology for positioning high-velocity SKUs near dispatch areas, a travel path analysis identifying the 3 most wasteful movement patterns in the current layout, a specific layout reconfiguration recommendation with before-and-after zone descriptions, staffing and workflow changes required to support the new layout, and the expected improvement in pick rate, order cycle time, and labor cost per order after implementation. Quantify the financial benefit at current order volume.","tags":["operations","logistics","optimization"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-66","title":"Production Outage Post-Mortem Report","prompt":"You are an IT operations manager writing a formal post-mortem report following a 6-hour production outage at a B2B SaaS company that affected 1,200 enterprise customers, caused an estimated $480,000 in SLA credit liability, and generated 340 support tickets. The incident was caused by a misconfigured database connection pool setting during a routine deployment that was not caught in staging. Write the complete post-mortem document including: a factual, blame-free incident timeline with 15-minute resolution increments, a root cause analysis using the 5-Whys methodology, a contributing factors section explaining what made the environment susceptible to this failure, an impact quantification (customers affected, revenue impact, and support volume), a corrective action plan with 8 specific action items assigned to owners with due dates, and a section on what went well during the incident response. Conclude with a 90-day prevention roadmap.","tags":["operations","technology","incident-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-67","title":"Tiered Customer Service SLA Framework","prompt":"You are a customer operations director designing a tiered Service Level Agreement framework for a 500-person software company with three customer segments: self-serve (8,000 customers, average ACV $800), mid-market (1,200 customers, average ACV $12,000), and enterprise (180 customers, average ACV $75,000). Design the complete SLA framework including: response time targets by tier and ticket severity (P1–P4), resolution time targets with methodology for calculating clock time versus business hours, escalation paths and trigger criteria, channel availability by tier (email, chat, phone, and dedicated CSM), and the compensation or credit mechanism for SLA breaches. Also include a support staffing model — given the current ticket volume of 1,800 tickets per week at an average handle time of 22 minutes — showing how many agents are needed per tier to meet the proposed SLAs with 95% confidence.","tags":["operations","customer-service","sla"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-68","title":"Post-Growth Operational Efficiency Audit","prompt":"You are a management consultant conducting an operational efficiency audit for a 200-person insurance brokerage firm that has experienced rapid growth from 80 to 200 employees in 18 months and now has significant process debt — duplicated work, unclear ownership, and systems that don't talk to each other. Design a 6-week operational audit framework covering 5 functional areas: Policy Administration, Claims Management, Client Services, Finance and Billing, and HR/People Ops. For each area, specify: the 3 key diagnostic questions, the data to collect (system reports, time studies, and interview guides), the benchmark metrics to measure against, and the red-flag indicators of significant inefficiency. At the end of Week 6, the audit should produce a prioritized opportunity map showing estimated hours wasted per week, potential FTE savings, and a 12-month improvement roadmap.","tags":["operations","audit","efficiency"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-69","title":"Last-Mile Delivery Cost Reduction Strategy","prompt":"You are a logistics optimization consultant working with an urban grocery delivery company that operates in 5 cities and is experiencing last-mile delivery costs of $11.20 per order against a target of $8.00. The company makes 4,200 deliveries per day using a fleet of 85 delivery drivers and processes orders in 90-minute delivery windows. Develop a last-mile cost reduction strategy addressing: route optimization improvements with specific technology and methodology recommendations and estimated savings per order; delivery density improvement through batching strategies, delivery window consolidation, and geo-clustering; fleet composition analysis with an owned versus gig economy driver mix recommendation; failed delivery reduction (current 8% failed first-attempt rate and a 5-step reduction plan); and customer communication improvements to reduce support contacts. Quantify the savings impact of each initiative and build the total path to $8.00 per order.","tags":["operations","logistics","supply-chain"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-70","title":"Business Continuity Plan for Fintech","prompt":"You are a business continuity planning specialist creating a Business Continuity Plan for a 350-person financial technology company that processes $2.8B in transactions monthly. The BCP must address 3 primary threat scenarios: extended cloud infrastructure outage (AWS us-east-1 regional failure), ransomware attack affecting internal systems, and key personnel unavailability (loss of 30%+ of the engineering team due to a health emergency). For each scenario, design: a crisis detection and declaration protocol specifying who decides and what criteria trigger BCP activation, a response team structure and communication tree, a system-by-system recovery priority order with RTO and RPO targets for each system tier, manual operating procedures for the 48-hour immediate response period, and customer communication templates. Include a BCP testing schedule with tabletop exercises and full failover tests, plus a quarterly review process to keep the plan current.","tags":["operations","risk-management","continuity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-71","title":"Procurement Transformation Strategy","prompt":"You are a chief procurement officer developing a 3-year procurement transformation strategy for a 1,000-person manufacturing company with $180M in annual third-party spend across 340 active suppliers. Current challenges include: no strategic sourcing function (all buying is tactical), tail spend of $28M that is unmanaged, 5 categories where the company is sole-sourced to a single vendor, and a procurement team of 8 people without category management experience. The strategy should cover: organizational design for a 15-person best-practice procurement team, a category management framework applied to the top 10 spend categories, a supplier rationalization plan targeting 40% reduction in supplier count over 3 years, a savings target methodology with a realistic Year 1 savings capture of $4–6M, and a technology roadmap covering e-sourcing, contract management, and spend analytics. Build a quarterly milestone plan for the first 12 months.","tags":["operations","procurement","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-72","title":"Change Management Plan Using ADKAR","prompt":"You are an organizational change management specialist using the Prosci ADKAR model. Develop a change management plan for a 400-person financial services company rolling out a mandatory shift from email-based approvals to a new digital workflow platform (ServiceNow) affecting 280 employees across Finance, Legal, HR, and Operations. The plan should cover: a stakeholder analysis matrix identifying 6 stakeholder groups by change impact level and change readiness, an ADKAR assessment showing the current state for each group, a targeted intervention plan for each phase of ADKAR (Awareness communications, Desire-building manager toolkit, Knowledge training design, Ability reinforcement, and Reinforcement measurement), a resistance management plan for the 3 most likely resistance sources, and a 16-week implementation timeline with change readiness checkpoints at weeks 4, 8, and 12. Include the 3 early warning metrics that indicate the rollout is at risk.","tags":["operations","change-management","hr"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-73","title":"Hybrid Workplace Strategy Analysis","prompt":"You are a workplace strategy consultant helping a 450-person technology company decide what to do with its 35,000 square foot headquarters lease that expires in 14 months. The company shifted to hybrid work in 2021 and current office utilization data shows 42% average occupancy on peak days (Tuesdays and Wednesdays), with less than 15% occupancy on Mondays and Fridays. Prepare a workplace strategy analysis covering: a utilization data summary and what it implies about actual space needs, a comparison of 4 space strategy options (renew current lease, downsize to 18,000 sq ft, move to flexible coworking, or move to a neighborhood hub model), a total cost of occupancy comparison for each option over 5 years, employee preference data you would recommend collecting before deciding, and a recommended option with a 12-month execution plan including lease negotiation strategy, fit-out design principles, and a move communication plan.","tags":["operations","workplace","real-estate"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-74","title":"SaaS Customer Onboarding Process Redesign","prompt":"You are a customer success operations consultant redesigning the customer onboarding process for a $22M ARR B2B SaaS company where time-to-value is currently 87 days (target: 45 days) and 28% of customers churn within 12 months before reaching their first major adoption milestone. Map and redesign the end-to-end onboarding process for a mid-market customer (100–500 users, $30,000 ACV). The redesign should include: a Day 0–Day 7 white-glove kickoff sequence with specific milestones and owner assignments, a self-serve enablement layer (in-app guidance, video library, and help center articles) that reduces live CSM time by 40%, a technical implementation checklist with escalation paths when integration timelines slip, a time-to-first-value definition and measurement methodology, automated health score triggers that alert the CSM team when a customer is at risk in the first 90 days, and a 30-45-60 day check-in framework. Include a staffing model showing how many CSMs are needed per 100 new customers.","tags":["operations","customer-success","process"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-75","title":"Inventory Optimization for Distributors","prompt":"You are a supply chain operations expert helping a 150-person specialty food and beverage distributor that carries 2,400 active SKUs and is experiencing simultaneous problems: $2.1M in slow-moving and obsolete inventory written off last year, and a 9% out-of-stock rate on its top 200 SKUs that cost an estimated $800,000 in lost sales. Design an inventory optimization plan that addresses both problems simultaneously. The plan should cover: an ABC/XYZ analysis framework to classify the 2,400 SKUs by both volume and demand variability, a revised reorder point and safety stock calculation methodology for each class, a SLOB prevention process including new product introduction criteria and 90/180-day review triggers, a supplier lead time variability reduction initiative targeting the 20 suppliers responsible for 60% of stockouts, and a 6-month implementation plan with inventory KPIs to track. Quantify the expected financial impact on working capital and lost sales.","tags":["operations","supply-chain","inventory"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // ── Startups & Entrepreneurship (b-76 to b-85) ──────────────────────────

  {"id":"b-76","title":"Series A Pitch Deck Narrative Builder","prompt":"You are a venture capital pitch coach who has helped founders raise over $400M in aggregate. Build a complete narrative arc and slide-by-slide content guide for a Series A pitch deck for an AI-powered legal document automation startup targeting small law firms (3–25 attorneys). The startup has $1.2M ARR, 85 paying customers, 92% gross retention, and is raising a $6M round at a $22M pre-money valuation. For each of the 12 slides (Problem, Solution, Product Demo, Market Size, Business Model, Traction, GTM Strategy, Competitive Landscape, Unit Economics, Team, Financials and Use of Funds, The Ask), provide: the core narrative message for that slide, 3–4 specific data points or story elements to include, what investors are really evaluating on that slide, and one common mistake to avoid. Format as a slide-by-slide guide the founder can use while building in Pitch or Keynote.","tags":["startups","fundraising","pitch-deck"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-77","title":"Seed-Stage SaaS Financial Model Structure","prompt":"You are a startup CFO advisor helping a pre-Series A founder build their first investor-grade financial model. The company is a B2B SaaS startup selling HR compliance software, currently at $180K ARR with 12 customers, planning to raise a $2.5M seed round. Build the complete structure and assumptions for a 36-month financial model. Specify: the revenue model structure using bottom-up projections from new logo additions, logo churn, and expansion; the key monthly unit assumptions for Year 1 (new logos per month, ACV, CAC, gross margin); the headcount plan by function for each year (sales, CS, engineering, G&A); the key operating expense drivers; working capital assumptions (monthly invoicing, 30-day payment terms); and the key output metrics (ARR, MRR, net burn, runway, gross margin %, and LTV:CAC). Provide worked numerical examples for Year 1 Month 6 calculations. Note the 5 assumptions investors will scrutinize most heavily.","tags":["startups","finance","financial-modeling"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-78","title":"B2B SaaS Go-to-Market Launch Strategy","prompt":"You are a go-to-market strategist with expertise in early-stage B2B SaaS launches. Develop a complete GTM strategy for a new AI-powered contract review tool launching to the mid-market segment (legal teams at 200–1,000 person companies). The product is ready for general availability and the founding team has a network of 8 potential design partner customers. The GTM strategy should cover: ideal customer profile definition with specific firmographic and technographic criteria, a 3-channel acquisition strategy for the first 6 months (founder-led outreach, inbound content, and one partnerships channel), a pricing strategy with rationale (per seat vs. per document vs. platform fee), a customer journey map from awareness to activation to first renewal, a launch milestone plan for Days 1–30, 31–90, and 91–180, and the 5 leading indicators you will track weekly to know whether the GTM strategy is working. Include budget allocation for a $150K first-6-months marketing budget.","tags":["startups","marketing","product-launch"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-79","title":"Co-Founder Agreement Key Terms Overview","prompt":"You are a startup legal advisor providing an informational overview (this is not legal advice — an attorney should review all agreements) of the key terms and decisions that two co-founders of a technology startup should address in a founders' agreement before incorporating. The two founders are splitting the company 60/40 (technical founder versus business founder). Cover the following critical areas with plain-English explanation of each decision and the most common market standard: equity vesting schedule (4-year vesting, 1-year cliff, and acceleration provisions for single versus double trigger), IP assignment (work-for-hire provisions and prior IP exclusion carve-outs), decision-making authority (reserved decisions requiring both founders' consent), salary and cash compensation in the pre-funding phase, what happens to equity if a founder departs (voluntary versus involuntary), and non-compete and non-solicitation provisions. Flag the 3 co-founder agreement provisions that most commonly cause disputes and explain why.","tags":["startups","legal","co-founders"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-80","title":"Monthly Investor Update Email Template","prompt":"You are a founder coach who has helped 50+ founders maintain strong investor relationships. Write a monthly investor update email template for an early-stage SaaS founder to send to 22 seed investors. The update should be structured to take the founder no more than 30 minutes to complete each month and take investors no more than 5 minutes to read. The template should include: a 3-sentence business momentum summary at the top (the headline number, one qualitative win, and one hard thing), a metrics section with 6 KPIs (ARR, MoM ARR growth, new customers added, churn, runway in months, and headcount), a 'What Went Well' section with 2–3 bullet points, a 'What Did Not Go Well' section with 2–3 bullet points (investors value founders who are candid about struggles), an 'Asks' section with the 2–3 specific things investors can help with this month, and a next month preview. Include guidance on tone — this email should be candid, not a PR exercise.","tags":["startups","fundraising","investor-relations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-81","title":"Product-Market Fit Diagnostic Framework","prompt":"You are a startup advisor specializing in early product-market fit assessment. Design a product-market fit diagnostic framework for a B2B SaaS startup that has 65 paying customers, $420K ARR, and is uncertain whether they have achieved sufficient PMF to scale sales from 2 to 10 AEs. The diagnostic should include: a PMF measurement methodology using 3 signals (Sean Ellis 'very disappointed' survey, NPS with open-ended follow-ups, and organic referral rate analysis) with specific threshold targets for each; a customer interview protocol for 8 deep-dive calls with the happiest customers to identify the exact job-to-be-done driving retention; a cohort retention analysis structure to identify which customer segments retain at 80%+ versus those churning within 6 months; a PMF Score calculation that synthesizes the three data sources into a single index; and a decision framework specifying at what PMF Score threshold the company should invest in scaling GTM versus continuing to iterate on product.","tags":["startups","product","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-82","title":"Post-Series A Hiring Prioritization Plan","prompt":"You are a startup scaling advisor helping a 12-person SaaS startup ($1.8M ARR, just closed a $4M Series A) prioritize its first 8 hires over the next 12 months. The founding team consists of 2 engineers (CEO is technical), 1 head of sales, and a head of marketing. Current team also has 8 engineers, 1 designer, and 1 customer success manager. Develop a hiring prioritization framework that helps the founders decide: which functional areas to build out first given the company's top 3 growth constraints (engineering velocity, sales capacity, and customer retention), how to sequence hires to avoid capability gaps (for example, hiring 3 AEs before building SDR support or a sales ops function), make-versus-buy decisions for non-core functions (accounting, legal, HR), and how to balance hiring generalists who can wear many hats versus specialists who need a defined scope. Include a month-by-month hiring plan with role names, start months, and rationale for each hire in priority order.","tags":["startups","hr","hiring"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-83","title":"Startup Pricing Experimentation Roadmap","prompt":"You are a pricing strategy consultant helping a 2-year-old B2B SaaS startup with $900K ARR that has never formally tested its pricing and suspects it is leaving significant revenue on the table. The product is a workflow automation tool for marketing teams, currently priced at a flat $299/month regardless of company size or usage. Design a structured pricing experimentation roadmap for the next 6 months. The roadmap should include: a customer willingness-to-pay research methodology with a conjoint analysis framework and 10 interview questions, a hypothesis for the optimal pricing metric (per seat, per workflow, or per active user), a staged A/B testing plan for new customer acquisition defining the test, control, sample size, and success criteria, a strategy for re-pricing existing customers without triggering churn (grandfathering logic, migration timeline, and communication templates), and a pricing governance process for ongoing optimization. Include estimated revenue impact scenarios for 3 pricing architectures.","tags":["startups","pricing","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-84","title":"Series B Quarterly Board Meeting Prep","prompt":"You are a chief of staff at a Series B startup helping the CEO prepare for a quarterly board meeting with 7 board members (3 lead investors, 2 independent directors, and 2 common board seats). The meeting is 3.5 hours. The company had a mixed quarter: ARR grew to $11M (8% below plan), gross margin improved to 72% from 68%, churn was elevated at 3.2% (versus 2.1% plan), the VP of Sales was terminated for performance after missing quota for 3 consecutive quarters, and a new partnership was signed with a major system integrator expected to contribute $800K ARR by year-end. Prepare: a board meeting agenda with time allocations, the top 3 sensitive topics and how to present them with credibility (elevated churn, VP departure, and a hiring plan gap), a metrics package structure with commentary on each variance, a set of 6 forward-looking questions the board is likely to ask with prepared answers, and a decision memo for one board resolution required (option pool expansion).","tags":["startups","governance","board-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-85","title":"Startup Competitive Moat Analysis","prompt":"You are a strategy advisor helping a Series A startup assess and strengthen its competitive defensibility before scaling go-to-market. The company provides AI-powered demand forecasting for specialty retailers and has $2.8M ARR across 32 customers. Three well-funded competitors have entered the market in the past 18 months. Conduct a competitive moat analysis covering: a framework for evaluating 6 potential sources of competitive advantage (data network effects, switching costs, proprietary algorithm differentiation, distribution advantages, brand trust, and ecosystem lock-in) with a current-state rating of 1–5 for each; identification of the 2 moats that are most achievable to build within 24 months at this company's resource level; a specific roadmap for building the top priority moat (quarterly milestones, required investments, and leading indicators of moat strength); a competitive response playbook for 3 scenarios a deep-pocketed competitor could use to attack (undercut on price, bundle with a larger platform, or acquire a key customer); and a 1-page 'Defensibility Story' narrative for investor conversations.","tags":["startups","strategy","competitive-analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // ── Legal & Executive (b-86 to b-100) ───────────────────────────────────

  {"id":"b-86","title":"Commercial MSA Contract Review Checklist","prompt":"You are a corporate legal advisor reviewing commercial contracts for business risk (this is a general risk framework, not legal advice — always have counsel review contracts). Create a comprehensive commercial contract review checklist for a mid-market software company's legal and operations teams to use when reviewing inbound customer Master Service Agreements. The checklist should cover 8 risk categories with specific clause-level review questions: (1) Intellectual Property (ownership, license scope, work-for-hire provisions), (2) Liability and Indemnification (cap amount, mutual vs. unilateral, carve-outs), (3) Data and Privacy (data processing terms, GDPR/CCPA compliance, breach notification obligations), (4) Payment Terms (invoicing, late payment, disputed invoices), (5) Termination (for cause, for convenience, effect of termination), (6) Governing Law and Dispute Resolution, (7) SLA and Service Credits, and (8) Change of Control provisions. For each category, flag the top 2 red-flag provisions that should trigger escalation to senior legal counsel.","tags":["legal","contracts","compliance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-87","title":"SEC Cybersecurity Disclosure Compliance Memo","prompt":"You are a VP of Compliance at a 400-person US-based financial services technology company preparing an executive memo for the CEO and board about the operational and compliance impact of newly finalized SEC regulations requiring enhanced cybersecurity incident disclosure within 4 business days of determining a material incident. Write the executive memo covering: a plain-English summary of the new requirement and its effective date, the specific changes to the company's current incident response process required to meet the 4-day disclosure window, the technology and workflow changes needed (incident tracking, materiality assessment framework, and legal review process), the estimated compliance implementation cost and timeline, the risk and liability exposure if the company fails to comply, and a recommended 90-day action plan with owners. Use an executive tone that conveys urgency without creating unnecessary alarm. Limit to 600 words.","tags":["legal","compliance","executive-communications"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-88","title":"GDPR and CCPA Privacy Impact Assessment","prompt":"You are a data privacy consultant helping a 300-person e-commerce company implement a GDPR and CCPA-compliant Data Privacy Impact Assessment process before launching a new AI-powered personalization engine that will process behavioral data on 2.4M registered customers. Design a complete DPIA framework that includes: a screening questionnaire to determine when a DPIA is required (8 yes/no questions with thresholds), a 7-section DPIA template covering data flow description, purpose and legal basis, data minimization assessment, risk identification (data breach, unauthorized access, and discrimination), risk mitigation measures with specific technical and organizational controls, a Data Protection Officer consultation record, and a final risk acceptance decision. Provide a worked example applying the framework to the AI personalization engine, including a sample risk register with 5 identified risks and their mitigations. Note the 3 scenarios that would require notifying a supervisory authority before launching.","tags":["legal","privacy","compliance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-89","title":"Post-Restructuring All-Hands CEO Script","prompt":"You are an executive communications coach helping a CEO prepare for an all-hands meeting addressing a difficult period: the company (450 employees, $85M revenue) has just completed a restructuring that included a 12% workforce reduction, a product line discontinuation, and a significant pivot in go-to-market strategy. The audience is the surviving 395 employees who are anxious, questioning their job security, and watching how leadership handles this moment. Write a 20-minute all-hands script covering: a 3-minute honest opening that acknowledges the difficulty of the moment without being defensive, a 5-minute explanation of why the decisions were made with genuine strategic rationale (not spin), a 5-minute articulation of the path forward with specific milestones for the next 2 quarters, a 4-minute section on what is NOT changing (values, culture commitments, and investment in the remaining team), and a 3-minute closing that is human and energizing without being tone-deaf. Include stage directions and pauses for emotional emphasis.","tags":["executive","communications","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-90","title":"Private Equity Board Report Template","prompt":"You are a chief of staff at a 600-person private equity-backed manufacturing company designing a quarterly board report template for a 9-member board. The report will be distributed 5 business days before each meeting as pre-read material. Design a complete board report template covering 8 sections: (1) Executive Summary — a half-page CEO narrative on the quarter's performance against plan, (2) Financial Highlights — P&L, balance sheet, and cash flow key metrics versus prior year and budget, (3) Revenue and Commercial Performance — sales pipeline, backlog, top 10 customers, and pricing trends, (4) Operations and Delivery — production output, quality metrics, and workforce data, (5) Strategic Initiatives — status dashboard for the 4 board-approved strategic projects, (6) Risk Management — top 5 enterprise risks with status update, (7) Outlook — revised full-year guidance with key assumptions, and (8) Decision Items — specific proposals requiring board approval. For each section, specify the exact tables, charts, and commentary required.","tags":["executive","governance","reporting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-91","title":"Executive Compensation Philosophy Design","prompt":"You are a compensation consultant designing an executive compensation philosophy for a 350-person private SaaS company preparing for a potential exit (IPO or strategic sale) in 3–5 years. The company currently has inconsistent executive pay across its 8 C-suite members, no formal peer benchmarking process, and two executives who have flagged compensation concerns. Design a complete executive compensation philosophy covering: the target pay positioning strategy (recommend P50 or P75 of a defined peer group with rationale), the pay mix recommendation for CEO, CFO, and VP-level executives (base, annual bonus, and equity as percentages of total compensation), an annual bonus design (target percentages by level, performance metrics weighting, and payout curve mechanics), an equity compensation strategy (option pool management, refresh grant philosophy, and vesting acceleration terms), and a peer group definition methodology for benchmarking. Include a communication plan for rolling out the new philosophy to the existing executive team.","tags":["executive","compensation","hr"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-92","title":"Data Breach Crisis Communications Strategy","prompt":"You are a crisis communications advisor with experience managing corporate crises at publicly traded and private companies. Develop a crisis communications strategy for a 500-person financial services company facing a data breach that exposed personal and financial information of 85,000 customers, discovered 48 hours ago and not yet publicly known. The strategy must address the next 72 hours. Cover: Hour 0–4 (internal escalation and crisis team activation — who is in the room, decision rights, and communication lockdown); Hour 4–24 (regulatory notification requirements including relevant state breach laws and financial services regulators, legal privilege preservation, and board notification); Hour 24–48 (customer notification preparation — the notification letter draft, call center script, FAQ document, and credit monitoring offer); and Hour 48–72 (media statement, press handling guidelines, employee talking points, and social media response protocol). Include a post-crisis communication plan for weeks 2–4. Flag the 3 communications mistakes that turn a manageable breach into a reputational crisis.","tags":["executive","communications","crisis-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"b-93","title":"C-Suite Succession Planning Framework","prompt":"You are an organizational development consultant designing a leadership succession planning process for a 700-person professional services firm where 4 of 7 C-suite executives are within 5 years of expected retirement and the company has historically promoted from outside at the executive level. Design a comprehensive succession planning framework covering: a talent pool identification process for identifying 'ready now,' 'ready in 1–2 years,' and 'ready in 3–5 years' candidates for each critical role; a development curriculum for each readiness band (specific experiences, stretch assignments, coaching, and training by band); an emergency succession protocol for sudden unexpected departures with at least 2 emergency successors identified per critical role; a governance model for conducting annual succession reviews at the board level; and a metrics framework for tracking succession bench health over time. Include specific guidelines for having succession conversations with high-potential employees that retain and energize them rather than creating false expectations.","tags":["executive","hr","leadership-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-94","title":"Global Compliance Training Program Design","prompt":"You are a compliance training director at a 1,200-person technology company designing a mandatory annual compliance training program to meet legal and regulatory requirements across 6 domains: Anti-Bribery and Corruption (FCPA and UK Bribery Act), Data Privacy (GDPR and CCPA), Information Security, Insider Trading Policy, Workplace Harassment and Discrimination, and Export Controls. The program must work for employees in 12 countries and be completable in under 90 minutes. Design the program structure including: module sequence and time allocation for each topic, role-based customization specifying which modules apply to all employees versus additional modules for managers, finance staff, and sales staff operating internationally, scenario-based learning design principles for each module with 2 example scenario titles per module, a knowledge assessment methodology (pass threshold and retake policy), a completion tracking and escalation process for non-completers, and a process for annual content refresh. Include a vendor evaluation framework for selecting an LMS and content provider.","tags":["legal","compliance","training"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-95","title":"Strategic Partnership Term Sheet Analysis","prompt":"You are a business development legal advisor (informational only, not legal advice) analyzing a proposed strategic partnership term sheet between a $35M ARR SaaS company and a $2B enterprise software company that wants to embed the SaaS product into its platform and sell it to its 8,000 enterprise customers. The proposed terms include: a 5-year exclusivity arrangement in the financial services vertical, a 30% revenue share on all embedded product sales, the enterprise partner's right to white-label the product and own the customer relationship, a minimum commitment of $2M in Year 1 scaling to $8M by Year 3, and a right of first refusal on acquisition for 24 months post-term. Analyze each term from the SaaS company's perspective: the risk-reward tradeoff, market standard comparison, the specific language changes to negotiate, and the walk-away conditions. Conclude with an overall recommendation on whether this partnership as structured accelerates or limits the company's long-term strategic position.","tags":["legal","partnerships","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-96","title":"First-Year ESG Strategy and Reporting Framework","prompt":"You are an ESG strategy consultant helping an 800-person B2B technology company build its first formal ESG program in response to enterprise customer procurement requirements, investor diligence questionnaires, and employee values alignment. The company has no current ESG reporting. Design a practical first-year ESG strategy and reporting framework covering: a materiality assessment process to identify the 8–10 ESG topics most relevant to the company's business model and stakeholders, the recommended reporting framework to adopt (GRI, SASB, or TCFD — recommend one with rationale), specific metrics and data collection processes for the top 5 ESG priorities (including Scope 1 and 2 emissions baseline, diversity metrics, employee wellbeing, data privacy governance, and community investment), a governance structure for ESG oversight (board committee, executive sponsor, and cross-functional working group), and a first annual ESG report structure. Include an honest assessment of the resource investment required and what is achievable in Year 1 versus Years 2–3.","tags":["executive","esg","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-97","title":"100-Day Post-Acquisition Integration Playbook","prompt":"You are an M&A integration director at a 1,500-person enterprise software company that has just closed an acquisition of a 120-person competitor for $85M. The acquired company operates on a different tech stack, has a separate brand identity, and has 12 shared customers with the acquirer. Design a 100-day integration playbook covering 5 workstreams: (1) People and Culture — employee communication cadence, retention package design for key talent, org structure decisions, and culture integration approach; (2) Product and Technology — immediate product roadmap rationalization decisions, technical integration timeline, and data migration plan; (3) Go-to-Market — brand strategy (maintain or consolidate), sales team integration, and customer communication approach for the 12 shared accounts; (4) Finance and Legal — system migration, entity consolidation timeline, and reporting integration; and (5) Operations — vendor contract review, facilities, and IT onboarding. For each workstream, specify the Day 1, Day 30, Day 60, and Day 100 milestones and the integration lead role responsible.","tags":["executive","mergers-acquisitions","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-98","title":"CEO Thought Leadership Content Strategy","prompt":"You are a B2B executive communications strategist helping the CEO of a $60M ARR supply chain software company build a thought leadership presence on LinkedIn and in industry media. The CEO is an expert in supply chain resilience but has never published content and is skeptical that it will drive business outcomes. Build a 6-month content strategy that is credible, sustainable, and directly supports commercial goals. The strategy should include: a point of view positioning statement that defines the CEO's unique perspective on supply chain transformation, a content pillar framework with 3 themes and 4–5 topic examples each, a realistic content calendar (2 LinkedIn posts per week, 1 long-form article per month, and 2 podcast appearances per quarter), a ghostwriting-to-authentic-voice workflow that takes no more than 30 minutes of the CEO's time per piece, success metrics for the program (audience growth, content engagement, and inbound inquiry attribution), and the 3 specific ways thought leadership will support the company's sales pipeline within 12 months.","tags":["executive","marketing","content"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-99","title":"Multi-State Employment Law Compliance Audit","prompt":"You are an HR compliance auditor conducting an annual employment law compliance review for a 450-person company with employees in California, New York, Texas, Illinois, and Washington state (this is informational only — consult qualified employment counsel for legal advice). Design a structured compliance audit checklist covering the 7 highest-risk employment law areas for a multi-state employer: (1) Wage and Hour compliance (FLSA and state-specific overtime, exempt classification, and meal and rest break requirements), (2) Leave Management (FMLA, state-specific family and medical leave, and paid sick leave requirements by state), (3) Anti-Discrimination and Harassment (written policy requirements, mandatory training hours by state, and investigation procedures), (4) Worker Classification (independent contractor tests by state, especially California AB5), (5) Pay Equity (equal pay act compliance and California pay transparency requirements), (6) I-9 and Employment Eligibility, and (7) Non-Compete Enforceability by state. For each area, identify the top 3 compliance gaps most commonly found in companies of this size and provide a remediation priority rating.","tags":["legal","hr","compliance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"b-100","title":"New CEO 100-Day Strategic Agenda","prompt":"You are an executive onboarding advisor helping a newly appointed CEO of a $120M revenue mid-market manufacturing company who is coming from outside the industry. The prior CEO led the company for 14 years and retired; the new CEO starts in 3 weeks and has 6 months before being expected to present a 3-year strategic plan to the board. Design a comprehensive 100-day agenda that balances learning, relationship-building, and early-impact actions. The agenda should include: a structured listening tour plan with internal and external stakeholder groups to meet, 5 key questions to ask in each category, and a synthesis methodology; a priority diagnostic framework for assessing the company's strategic position, financial health, organizational capability, and culture in the first 30 days; a decision framework for identifying which of the prior CEO's priorities to continue, accelerate, modify, or stop; a communication plan for building credibility with the board, employees, customers, and investors; a personal brand-setting moment in the first 60 days; and a Day 100 output: a crisp preliminary strategic hypothesis document to share with the board before the full 3-year plan development begins.","tags":["executive","leadership","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true}

];
